import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.util.logging.Logger;

public static boolean copyFolder(File source, File target, Logger log) {
    Path sourcePath = source.toPath();
    Path destPath = target.toPath();
    try {
        Files.walk(sourcePath)
             .forEach(src -> {
                 try {
                     Path targetPath = destPath.resolve(sourcePath.relativize(src));
                     Files.copy(src, targetPath, StandardCopyOption.REPLACE_EXISTING);
                 } catch (IOException e) {
                     log.warning(e.getMessage());
                 }
             });
        return true;
    } catch (IOException e) {
        log.warning(e.getMessage());
        return false;
    }
}

